/**
 * Filesystem discovery: walks a project's `bot/` directory and compiles
 * the authored files (markdown and TypeScript) into an {@link AgentProject}
 * manifest. Identity comes from the path — a tool at `bot/tools/foo.ts`
 * is named `foo`, a subagent at `bot/subagents/researcher/` is named
 * `researcher` — so no definition carries a `name` field.
 *
 * The loaders live under `./discovery/`, one module per authored slot;
 * this module is the public surface the CLI, server, and tests import.
 */
export { DEFAULT_AGENT_ARCHITECTURE } from "./discovery/agent-config.js";
export { projectInfo } from "./discovery/info.js";
export { formatDiagnostics, formatValidateJson, hasErrorDiagnostics, isAgentProjectDir, listChildAgentDirs, loadAgentProject, loadAgentProjects, resolveAgentMounts, } from "./discovery/project.js";
